```javascript
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, noise, uniform, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, SRGBColorSpace } = THREE;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const cSurface = new Color(colors.surface);
  const cInk = new Color(colors.ink);
  const cAccent = new Color(colors.accent);

  // Atlas region 0, 0, 512, 320 -> aspect ratio 8:5
  const cardW = 1.6;
  const cardH = 1.0;

  // ── Card backdrop: engineered gradient + subtle grain ──
  const bgGeo = new PlaneGeometry(cardW, cardH);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  const sCol = vec3(cSurface.r, cSurface.g, cSurface.b);
  const iCol = vec3(cInk.r, cInk.g, cInk.b);

  const gradY = smoothstep(0.0, 1.0, uv().y);
  const gradient = mix(sCol, iCol, gradY);

  // engineered gradient: subtle diagonal shift
  const gradX = smoothstep(-0.3, 1.3, uv().x.oneMinus());
  const gradientDiag = mix(sCol.mul(1.15), gradient, gradX);

  // subtle grain
  const grain = noise(uv().mul(350.0)).mul(0.025);

  // faint accent vignette at bottom edge
  const accentTint = vec3(cAccent.r, cAccent.g, cAccent.b)
    .mul(smoothstep(0.85, 0.0, uv().y).mul(0.08));

  bgMat.colorNode = gradientDiag.add(grain).add(accentTint);

  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = 0.0;
  group.add(bg);

  // ── Decorative orb texture overlay ──
  const orbGeo = new PlaneGeometry(cardW, cardH);
  const orbMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  // texture uniform so colorNode can reference it once loaded
  const texUniform = uniform(null);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = SRGBColorSpace;
    texUniform.value = tex;
    orbMat.needsUpdate = true;
  });

  // when texture is null, output transparent; once loaded, composite over subtle gradient
  const orbBase = texture(texUniform, uv());
  orbMat.colorNode = orbBase;

  const orb = new Mesh(orbGeo, orbMat);
  orb.position.z = 0.001;
  group.add(orb);

  // ── Entrance: rise-in (y +0.4 -> 0, power3.out, 0.7s) ──
  group.position.y += 0.4;
  group.visible = true;
  const tl = gsap.timeline();
  tl.to(group.position, {
    y: group.position.y - 0.4,
    duration: 0.7,
    ease: 'power3.out'
  });
  tl.from(bg.material, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0);
  tl.from(orb.material, { opacity: 0, duration: 0.5, ease: 'power2.out' }, 0.1);

  // ── Cleanup ──
  group.userData.cleanup = () => {
    tl.kill();
    bgGeo.dispose();
    bgMat.dispose();
    orbGeo.dispose();
    orbMat.dispose();
    if (texUniform.value) texUniform.value.dispose();
  };

  return group;
}
